#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

int main(int argc, char **argv) {
    /* ---------- 1. argument validation ---------- */
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *input = argv[1];
    size_t n = strlen(input);
    if (n == 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < n; ++i) {
        if (input[i] != '0' && input[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    /* ---------- 2. mutable tape ---------- */
    char *tape = malloc(n);
    if (!tape) return 1;               /* out of memory – not expected */
    memcpy(tape, input, n);

    /* ---------- 3. Turing‑machine simulation ---------- */
    size_t head = 0;          /* index on the tape, LSB is at 0 */
    int state = 0;            /* 0 = search first 0, 1 = reset visited 1s */
    long long steps = 0;      /* step counter, matches original */
    bool overflow = false;

    while (true) {
        ++steps;   /* every transition counts as a step */

        if (state == 0) {                     /* searching for first 0 */
            if (head >= n) {                  /* all bits were 1 */
                overflow = true;
                break;
            }
            if (tape[head] == '1') {
                ++head;                       /* move right */
            } else { /* tape[head] == '0' */
                tape[head] = '1';             /* turn 0 into 1 */
                if (head == 0) {              /* would move left off tape */
                    overflow = true;
                    break;
                }
                --head;                       /* move left */
                state = 1;                    /* start resetting */
            }
        } else {                               /* state == 1 : reset */
            if (head == (size_t)-1) {          /* moved left of the tape */
                overflow = true;
                break;
            }
            if (tape[head] == '1') {
                tape[head] = '0';            /* turn 1 into 0 */
                if (head == 0) {              /* next move would be off tape */
                    overflow = true;
                    break;
                }
                --head;                       /* keep moving left */
            } else { /* tape[head] == '0' */
                /* carry resolved – finished */
                break;
            }
        }
    }

    /* ---------- 4. output ---------- */
    if (overflow) {
        puts("OVERFLOW");
    } else {
        printf("result=");
        for (size_t i = 0; i < n; ++i)
            putchar(tape[i]);
    }
    printf(" steps=%lld\n", steps);

    free(tape);
    return 0;
}
